# Generates d3dx8_shaders.inl: the pixel shaders the game assembles at run time with D3DXAssembleShader,
# precompiled with the real 32-bit d3dx8.lib, for the x64 build where d3dx8 does not exist.
#
# Run from an x86 Visual Studio command prompt (cl.exe for x86 in PATH):
#   python generate_shader_table.py <repo root> <min-dx8-sdk dir with d3dx8.lib>
#
# The shader source literals are copied verbatim from the game sources into a small program, so the
# strings are byte for byte the ones the game passes (the water shaders use backslash line continuations).
import os, re, subprocess, sys, tempfile

SOURCES = [
    'Core/GameEngineDevice/Source/W3DDevice/GameClient/Water/W3DWater.cpp',
    'Core/GameEngineDevice/Source/W3DDevice/GameClient/W3DProfilerFrameCapture.cpp',
]

TOOL = r'''#include <windows.h>
#include <d3dx8.h>
#include <stdio.h>
#include <string.h>

static const char *const kShaders[] = {
%(literals)s
};

int main(int argc, char **argv)
{
	FILE *out = fopen(argv[1], "wb");
	if (!out) return 1;
	fprintf(out, "// Generated by generate_shader_table.py with the 32-bit d3dx8.lib. Do not edit.\r\n");
	for (size_t i = 0; i < sizeof(kShaders) / sizeof(kShaders[0]); ++i)
	{
		const char *src = kShaders[i];
		LPD3DXBUFFER code = NULL, errors = NULL;
		HRESULT hr = D3DXAssembleShader(src, (UINT)strlen(src), 0, NULL, &code, &errors);
		if (FAILED(hr))
		{
			fprintf(stderr, "shader %%u failed: %%s\n", (unsigned)i, errors ? (const char *)errors->GetBufferPointer() : "?");
			return 2;
		}
		fprintf(out, "static const char kShaderSource%%u[] =\r\n\t\"", (unsigned)i);
		for (const char *p = src; *p; ++p)
		{
			unsigned char c = (unsigned char)*p;
			if (c == '\\' || c == '"') fprintf(out, "\\%%c", c);
			else if (c == '\n') fprintf(out, "\\n\"\r\n\t\"");
			else if (c == '\t') fprintf(out, "\\t");
			else if (c < 32 || c > 126) fprintf(out, "\\x%%02x\"\"", c);
			else fputc(c, out);
		}
		fprintf(out, "\";\r\nstatic const DWORD kShaderCode%%u[] = {", (unsigned)i);
		const DWORD *words = (const DWORD *)code->GetBufferPointer();
		const DWORD count = code->GetBufferSize() / sizeof(DWORD);
		for (DWORD w = 0; w < count; ++w)
			fprintf(out, "%%s0x%%08lX,", (w %% 8) ? " " : "\r\n\t", words[w]);
		fprintf(out, "\r\n};\r\n\r\n");
		code->Release();
		if (errors) errors->Release();
	}
	fprintf(out, "static const PrecompiledShader kPrecompiledShaders[] = {\r\n");
	for (size_t i = 0; i < sizeof(kShaders) / sizeof(kShaders[0]); ++i)
		fprintf(out, "\t{ kShaderSource%%u, sizeof(kShaderSource%%u) - 1, kShaderCode%%u, sizeof(kShaderCode%%u) },\r\n",
			(unsigned)i, (unsigned)i, (unsigned)i, (unsigned)i);
	fprintf(out, "};\r\n");
	fclose(out);
	return 0;
}
'''


def statement_end(text, pos):
    """Index of the ';' ending the C statement at pos; ';' inside string literals (shader comments) is skipped."""
    in_string = False
    i = pos
    while i < len(text):
        c = text[i]
        if in_string:
            if c == '\\':
                i += 2  # escape sequence or line continuation (\ + CR/LF handled by the next character)
                continue
            if c == '"':
                in_string = False
        elif c == '"':
            in_string = True
        elif c == ';':
            return i
        i += 1
    raise ValueError('unterminated statement')


def shader_literals(path):
    """Every string literal assigned to `shader` right before a D3DXAssembleShader call, verbatim."""
    text = open(path, 'rb').read().decode('latin1')
    found = []
    for m in re.finditer(r'(?:const\s+char\s*\*\s*)?\bshader\s*=\s*', text):
        end = statement_end(text, m.end())
        if 'D3DXAssembleShader' in text[end:end + 400]:
            found.append(text[m.end():end].strip())
    return found


def main():
    root, sdk = sys.argv[1], sys.argv[2]
    literals = []
    for rel in SOURCES:
        lits = shader_literals(os.path.join(root, rel))
        if not lits:
            sys.exit('no shaders found in ' + rel)
        literals += lits
    work = tempfile.mkdtemp()
    tool = os.path.join(work, 'assemble_shaders.cpp')
    open(tool, 'wb').write((TOOL % {'literals': ',\r\n'.join(literals)}).encode('latin1'))
    exe = os.path.join(work, 'assemble_shaders.exe')
    subprocess.check_call(['cl', '/nologo', '/EHsc', '/I', sdk, tool, '/Fe' + exe, '/Fo' + work + '\\',
                           '/link', '/LIBPATH:' + sdk, 'd3dx8.lib', 'd3d8.lib', 'legacy_stdio_definitions.lib', 'gdi32.lib', 'advapi32.lib', 'user32.lib',
                           '/NODEFAULTLIB:libci.lib', '/SAFESEH:NO'])
    out = os.path.join(root, 'Dependencies', 'D3DX8Compat', 'd3dx8_shaders.inl')
    subprocess.check_call([exe, out])
    print('wrote %s (%d shaders)' % (out, len(literals)))


if __name__ == '__main__':
    main()
